// M4 PoC Step 1: Create isolated test project "Agent_Hello_Circuit" (.eprj3),
// create a board/schematic, open the schematic sheet, look up active JLCPCB Basic parts,
// place R1, R2, C1, R3, LED1, and return exact pin coordinates & names for Step 2 wiring.

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const projUuid = await eda.dmt_Project.createProject(
  "Agent_Hello_Circuit",
  "agent-hello-circuit",
  undefined,
  undefined,
  "M4 Hello Circuit PoC generated by ADX Agent over MCP",
  undefined,
  EDMT_ProjectFileFormat.EPRJ3
);
if (!projUuid) {
  throw new Error("createProject returned undefined");
}

await eda.dmt_Project.openProject(projUuid);
await sleep(2500);
if (eda.dmt_Project.waitForReady) {
  await eda.dmt_Project.waitForReady();
}

const boardName = await eda.dmt_Board.createBoard();
await sleep(2500);
if (eda.dmt_Project.waitForReady) {
  await eda.dmt_Project.waitForReady();
}

const pages = await eda.dmt_Schematic.getAllSchematicPagesInfo();
if (!pages || pages.length === 0) {
  throw new Error("No schematic pages found after createBoard()");
}
const pageUuid = pages[0].uuid;
await eda.dmt_EditorControl.openDocument(pageUuid);
await sleep(2500);

// Look up active JLCPCB Basic parts via LCSC ID
const devR1k  = await eda.lib_Device.getByLcscIds("C21190"); // 1k 0603 Basic
const devR10k = await eda.lib_Device.getByLcscIds("C25804"); // 10k 0603 Basic
const devC100 = await eda.lib_Device.getByLcscIds("C14663"); // 100nF 0603 Basic
const devLed  = await eda.lib_Device.getByLcscIds("C2286");  // Red LED 0603 Basic

const toRef = (d) => ({
  libraryType: "3",
  libraryUuid: d.libraryUuid,
  uuid: d.uuid,
});

// Place components neatly centered on A4 sheet (origin bottom-left, Y up, unit=10mil)
// Voltage divider + RC filter on left/middle; LED indicator on right.
const placements = [
  { ref: "R1",   lcsc: "C21190", dev: devR1k,  x: 420, y: 560, rot: 90 },
  { ref: "R2",   lcsc: "C25804", dev: devR10k, x: 420, y: 400, rot: 90 },
  { ref: "C1",   lcsc: "C14663", dev: devC100, x: 560, y: 400, rot: 90 },
  { ref: "R3",   lcsc: "C21190", dev: devR1k,  x: 720, y: 560, rot: 90 },
  { ref: "LED1", lcsc: "C2286",  dev: devLed,  x: 720, y: 400, rot: 270 },
];

const placed = [];
for (const item of placements) {
  const c = await eda.sch_PrimitiveComponent.create(
    toRef(item.dev),
    item.x,
    item.y,
    undefined,
    item.rot,
    false,
    true,
    true
  );
  const id = c.getState_PrimitiveId();
  const cur = await eda.sch_PrimitiveComponent.get(id);
  const otherProp = cur.getState_OtherProperty() || {};
  await eda.sch_PrimitiveComponent.modify(id, {
    designator: item.ref,
    otherProperty: otherProp,
  });
  const pins = await eda.sch_PrimitiveComponent.getAllPinsByPrimitiveId(id);
  placed.push({
    ref: item.ref,
    lcsc: item.lcsc,
    partClass: item.dev?.otherProperty?.["JLCPCB Part Class"],
    partName: item.dev?.name,
    id,
    rot: item.rot,
    pins: pins.map((p) => ({
      number: p.pinNumber ?? p.getState_PinNumber?.(),
      name: p.pinName ?? p.getState_PinName?.(),
      x: p.x ?? p.getState_X?.(),
      y: p.y ?? p.getState_Y?.(),
    })),
  });
}

await eda.sch_Document.save();

return {
  projUuid,
  boardName,
  pageUuid,
  projInfo: await eda.dmt_Project.getCurrentProjectInfo(),
  placed,
};
